# i.e., the two frame neighbors should share a line with additional frame cells

def check_frame_alignment(grid, r, c, frame, direction):
    """
    direction = 'V' for vertical alignment, 'H' for horizontal
    Check if the two frame neighbors can be connected by a line of frame cells
    """
    if direction == 'V':  # Check if top or bottom neighbor is in a vertical line of frames
        for dr, dc in [(1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and grid[nr][nc] == frame:
                # Count consecutive frames in direction
                count = 0
                for i in range(1, 15):
                    nnr = nr + dr * i
                    if 0 <= nnr < len(grid) and grid[nnr][nc] == frame:
                        count += 1
                    else:
                        break
                return count >= 2  # At least one more frame cell besides neighbor
    elif direction == 'H':  # Check if left or right neighbor is in a horizontal line of frames
        for dc in [1, -1]:
            nc = c + dc
            if 0 <= nc < len(grid[0]) and grid[r][nc] == frame:
                for i in range(1, 15):
                    nnr = c + dc * (i + 1)
                    if 0 <= nnr < len(grid[0]) and grid[r][nnr] == frame:
                        return True
                    else:
                        break
    return False

