def check_consecutive_frame(row_idx, col_idx, test_in, frame_val):
    """Check how many consecutive frames going away from cell in each direction"""

    # Right direction
    right_count = 0
    for c in range(col_idx + 1, len(test_in[row_idx])):
        if test_in[row_idx][c] == frame_val:
            right_count += 1
        else:
            break

    # Left direction
    left_count = 0
    for c in range(col_idx - 1, -1, -1):
        if test_in[row_idx][c] == frame_val:
            left_count += 1
        else:
            break

    # Up direction
    up_count = 0
    for r in range(row_idx - 1, -1, -1):
        if test_in[r][col_idx] == frame_val:
            up_count += 1
        else:
            break

    # Down direction
    down_count = 0
    for r in range(row_idx + 1, len(test_in)):
        if test_in[r][col_idx] == frame_val:
            down_count += 1
        else:
            break

    return {
        'right': right_count,
        'left': left_count,
        'up': up_count,
        'down': down_count
    }

def has_long_consecutive(neighbors, frame_val):
    """Check if at least one direction has >= 2 consecutive frames"""
    return (neighbors['right'] >= 2 or neighbors['left'] >= 2 or 
            neighbors['up'] >= 2 or neighbors['down'] >= 2)

